package com.shopsphere;import static org.assertj.core.api.Assertions.*;import java.sql.DriverManager;import org.junit.jupiter.api.Test;import org.testcontainers.containers.MySQLContainer;import org.testcontainers.junit.jupiter.*;
@Testcontainers(disabledWithoutDocker=true)class OrderPersistenceContainerTest{@Container static MySQLContainer<?>mysql=new MySQLContainer<>("mysql:8.4");@Test void uniqueOrderNumberIsEnforced()throws Exception{try(var c=DriverManager.getConnection(mysql.getJdbcUrl(),mysql.getUsername(),mysql.getPassword());var s=c.createStatement()){s.execute("CREATE TABLE order_probe(id INT PRIMARY KEY,number VARCHAR(20) UNIQUE)");s.executeUpdate("INSERT INTO order_probe VALUES(1,'SS-1')");assertThatThrownBy(()->s.executeUpdate("INSERT INTO order_probe VALUES(2,'SS-1')")).isInstanceOf(java.sql.SQLException.class);}}}
